text:
Skill 3 looks like XOR of two hidden per-input codes, because rows differ by a constant XOR 55% of the time. Skills 0-2 lean toward add mod 16. I search hidden code tables g(a), h(b) for each operation against the net's predictions, with a random table as the null. This fits symbols only, not weights.
```python
P=np.load("pred1500.npy")
rng=np.random.default_rng(0)
ops={"add":(lambda g,h:(g+h)%16, lambda y,h:(y-h)%16, lambda y,g:(y-g)%16),
     "xor":(lambda g,h:g^h, lambda y,h:y^h, lambda y,g:y^g),
     "sub":(lambda g,h:(g-h)%16, lambda y,h:(y+h)%16, lambda y,g:(g-y)%16)}
def fit(T,op,restarts=30,iters=30):
    f,ga,hb=ops[op]; best=(-1,None,None)
    for r in range(restarts):
        h=rng.integers(0,16,32); g=np.zeros(32,int)
        for it in range(iters):
            for a in range(32): g[a]=np.bincount(ga(T[a],h),minlength=16).argmax()
            for b in range(32): h[b]=np.bincount(hb(T[:,b],g),minlength=16).argmax()
        acc=(f(g[:,None],h[None,:])==T).mean()
        if acc>best[0]: best=(acc,g.copy(),h.copy())
    return best
res={}
for s in range(4):
    line=[]
    for op in ("add","xor"):
        acc,g,h=fit(P[s],op); res[(s,op)]=(acc,g,h); line.append((op,round(float(acc),3)))
    print("skill",s,line)
null=rng.integers(0,16,(32,32))
print("null",round(float(fit(null,"add")[0]),3),round(float(fit(null,"xor")[0]),3))
for k,v in res.items():
    print(k,round(float(v[0]),3),"g",v[1].tolist(),"h",v[2].tolist())
np.save("fits.npy",np.array([[res[(s,op)][1:] for op in ("add","xor")] for s in range(4)],dtype=object),allow_pickle=True)
