text:
The fits (add .51-.57, xor .72) match what train accuracy on 70% of pairs would allow, so the rules may be exact. The test: refine the codes with soft scores, then check agreement on the net's confident cells, which should be near 100% if the rules hold.
```python
def silu(x): return x/(1+np.exp(-x))
def fwd(W):
    X=np.zeros((4096,68)); i=0
    for s in range(4):
        for a in range(32):
            for b in range(32):
                X[i,a]=1;X[i,32+b]=1;X[i,64+s]=1;i+=1
    h=silu(X@W["l1.weight"].T+W["l1.bias"]); h=silu(h@W["l2.weight"].T+W["l2.bias"]); return h@W["l3.weight"].T+W["l3.bias"]
def lp(W):
    L=fwd(W)[:,:16]; L=L-L.max(1,keepdims=True); L=L-np.log(np.exp(L).sum(1,keepdims=True)); return L.reshape(4,32,32,16)
LP=lp({n:load(n) for n in NAMES}); np.save("lp1500.npy",LP)
rng=np.random.default_rng(1)
OPS=["add","add","add","xor"]
def tab(g,h,op): return (g[:,None]+h[None,:])%16 if op=="add" else g[:,None]^h[None,:]
def softfit(S,op,restarts=40):
    best=(-1e18,None,None); I=np.arange(32)
    for r in range(restarts):
        h=rng.integers(0,16,32); g=np.zeros(32,int)
        for it in range(25):
            sc=np.zeros((32,16))
            for v in range(16):
                y=(v+h)%16 if op=="add" else v^h
                sc[:,v]=S[:,I,y].sum(1)
            g=sc.argmax(1)
            sc=np.zeros((32,16))
            for v in range(16):
                y=(g+v)%16 if op=="add" else g^v
                sc[:,v]=S[I,:,y].sum(0)
            h=sc.argmax(1)
        T=tab(g,h,op); val=S[I[:,None],I[None,:],T].sum()
        if val>best[0]: best=(val,g.copy(),h.copy())
    return best
out={}
for s in range(4):
    S=LP[s]; val,g,h=softfit(S,OPS[s]); T=tab(g,h,OPS[s]); out[s]=(g,h)
    P=S.argmax(2); pm=np.exp(S.max(2))
    print("skill",s,OPS[s],"agree %.3f"%(P==T).mean(),"by confidence",[(th,int((pm>th).sum()),round(float((P==T)[pm>th].mean()),3)) for th in (.3,.5,.7,.9,.97)])
    print(" g",g.tolist()); print(" h",h.tolist())
    # margin of each code entry
    I=np.arange(32); sc=np.zeros((32,16))
    for v in range(16): sc[:,v]=S[:,I,(v+h)%16 if OPS[s]=="add" else v^h].sum(1)
    ss=np.sort(sc,1); print(" a-margin min/median",round(float((ss[:,-1]-ss[:,-2]).min()),1),round(float(np.median(ss[:,-1]-ss[:,-2])),1))
    sc=np.zeros((32,16))
    for v in range(16): sc[:,v]=S[I,:,(g+v)%16 if OPS[s]=="add" else g^v].sum(0)
    ss=np.sort(sc,1); print(" b-margin min/median",round(float((ss[:,-1]-ss[:,-2]).min()),1),round(float(np.median(ss[:,-1]-ss[:,-2])),1))
    # residual offsets where the net disagrees and is confident
    D=((P-T)%16 if OPS[s]=="add" else P^T)
    print(" residual hist (conf>.5)",np.bincount(D[pm>.5],minlength=16).tolist())
np.savez("codes.npz",**{f"g{s}":out[s][0] for s in out},**{f"h{s}":out[s][1] for s in out})
